class Obj {
	constructor(clr) {
		this.x = random(width * 0.1, width * 0.9);
		this.y = random(height * 0.1, height * 0.9);
		this.clr = clr;
		this.step = ~~random(2, 4)
		this.poss = [];
		this.dir = createVector(0, -1);
		this.lifetime = ~~random(45, 135)
	}

	grow() {
		const x = this.x + this.dir.x;
		const y = this.y + this.dir.y;
		this.poss.push({x, y});
	}

	show() {
		push();
		noFill()
		stroke(this.clr[0]);
		var x, y, px = this.x, py = this.y;
		for (p of poss) {
			x = p.x;
			y = p.y;
			line(px, py, x, y)
			px = x;
			py = y;
		}
		pop();
	}	
}

