var num = 16;
var clrs1, clrs2;

function setup() {
	createCanvas(windowWidth, windowHeight);
	describe("16 rows or columns consisting of 16 segements different sizes and alternating colors. Postprocessing with vignette effect and interlace lines.")

	pixelDensity(1)
	colorMode(HSB, 100);
	frameRate(30);
	clrs1 = genColors(num * 2);
	clrs2 = clrs1.splice(0, num);

	const seed = random(year()+month()+day()+hour()+minute()+second());
	console.log(`seed ${seed}`);
	randomSeed(seed)
}

function draw() {
	const bg = color("rgb(0,0,12)");
	background(bg);

	let drawHoriz = true, drawVert = false;
	if (random()<0.5) [drawHoriz,drawVert] = [drawVert, drawHoriz];

	let rnd = ~~random(3);
	drawHoriz = rnd === 0 || rnd === 2;
	drawVert = rnd === 1 || rnd === 2;

	let drawSym = random() < 0.2;
	if (drawSym) {
		drawHoriz = drawVert = false;
	}

	if (drawSym) {
		let valsX = [], sumX = 0;
		let valsY = [], sumY = 0;
		// get values 0..1
		for (i = 0; i < num; i++) {
			valsX[i] = random(0.01, 1);
			sumX += valsX[i];
			valsY[i] = random(0.01, 1);
			sumY += valsY[i];
		}
		// normalize
		for (i = 0; i < num; i++) {
			valsX[i] = valsX[i]/sumX;
			valsY[i] = valsY[i]/sumY;
		}

		var x = 0;
		for (xi = 0; xi < num; xi++) {
			let w = valsX[xi] * width;

			const clrs = random([clrs1, clrs2])
			const c1 = ~~random(clrs.length);
			const c2 = (c1+1) % clrs.length;
			const cs = [clrs[c1], clrs[c2]];

			var y = 0;
			for (yi = 0; yi < num; yi++) {
				let h = valsY[yi] * height;
				noStroke();
				fill(cs[yi%cs.length])
				for (j = 0; j < num; j++) {
					push();
					const d = w * 0.1;
					translate(random(-d, d), random(-d, d))
					rect(x, y, x + w, y + h)				
					pop();
				}
				y += h;
			}
			x += w;
		}
	} 

	// vertical top down
	if (drawVert) {
		var w = width / num;
		for (x = 0; x < width; x += w) {
			let vals = [], sum = 0;
			for (i = 0; i < num; i++) {
				vals[i] = random(0.01, 1);
				sum += vals[i];
			}

			var c1 = ~~random(clrs1.length);
			var c2 = (c1+1) % clrs1.length;
			var cs = [clrs1[c1], clrs1[c2]];

			var y = 0;
			for (i = 0; i < num; i++) {
				vals[i] = vals[i]/sum;
				var h = vals[i] * height;
				noStroke();
				fill(cs[i%cs.length])
				for (j = 0; j < num; j++) {
					push();
					var d = w * 0.1;
					translate(random(-d, d), random(-d, d))
					rect(x, y, x + w, y + h)				
					pop();
				}
				y += h;
			}
		}
	} 
	// vertical top down

	// hotizontal left right
	if (drawHoriz) {
		var h = height / num;
		for (y = 0; y < height; y += h) {
			if (drawVert && random() < 0.75) continue;

			var vals = [], sum = 0;
			for (i = 0; i < num; i++) {
				vals[i] = random(0.01, 1);
				sum += vals[i];
			}

			var c1 = ~~random(clrs2.length);
			var c2 = (c1+1) % clrs2.length;
			var cs = [clrs2[c1], clrs1[c2]];

			var x = 0;
			for (i = 0; i < num; i++) {
				vals[i] = vals[i]/sum;
				var w = vals[i] * width;
				noStroke();
				fill(cs[i%cs.length])
				for (j = 0; j < num; j++) {
					push();
					var d = h * 0.1;
					translate(random(-d, d), random(-d, d))
					rect(x, y, x + w, y + h)				
					pop();
				}
				x += w;
			}
		}
	} 
	// hotizontal left right

	drawBackground(bg);

	// noLoop() removed for animation
}

function drawBackground(bg) {
	// background(bg);
	push()
	const ctx = drawingContext;
	const gradient = ctx.createRadialGradient(
		width/2, height/2, max(width, height)/1000, 
		width/2, height/2, max(width, height)*0.65
	);

	// Add three color stops
	gradient.addColorStop(0, color(0, 0, 100, 1));
	gradient.addColorStop(1, bg);

	// Set the fill style and draw a rectangle
	ctx.fillStyle = gradient;
	ctx.fillRect(0, 0, width, height);

	stroke(0, 0, 100, 50)
	strokeWeight(1.25)
	for (y = 3; y < height; y += 4) {
		line(0, y, width, y)
	}

	pop()
}

// colors
function genColors(n = 2, keepF = 1, space = 100) {
	arr = [];
	const HUE = ~~random(100)
	const DLT = space / n;
	for (i = 0; i < n; i++) {
		let clr = color((HUE + i * DLT) % 100, random(65, 95), random(65, 95), 15);
		arr.push(clr)
	}
	arr = arr.splice(0, ~~(arr.length * keepF))
	return arr;
}

// interaction
function mousePressed() {
	if (mouseButton === LEFT) {
		setup();
		draw();
	}
}
